"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[29],{20029:a=>{a.exports=JSON.parse('{"meta":{"title":"Relawan - iMuslim Life","description":"Bantu umat Islam di seluruh dunia salat tepat waktu dan membaca Al-Qur\u2019an dalam bahasa mereka. Jadilah relawan penerjemah, qari, peninjau, penulis, penguji, atau duta masjid."},"chip":"Jadi relawan","h1":"Keahlian Anda bisa menjadi sedekah jariyah","lede":"Salat-e-Mustaqeem dan iMuslim Life gratis, tanpa iklan, dan dipakai setiap hari oleh umat Islam di seluruh dunia. Beberapa jam waktu Anda dapat membantu seseorang salat tepat waktu, memahami Al-Qur\u2019an dalam bahasanya, atau menemukan masjid terdekat, berulang kali.","heroCta":"Kirim email untuk menjadi relawan","hadith":{"text":"\u201cBarang siapa menunjukkan kepada kebaikan, maka baginya pahala seperti orang yang mengerjakannya.\u201d","source":"Nabi Muhammad shallallahu \u2018alaihi wasallam, Shahih Muslim 1893"},"why":"Setiap kata yang Anda terjemahkan dibaca oleh orang-orang yang tak akan pernah Anda temui. Setiap bacaan yang Anda rekam didengar di rumah, mobil, dan masjid. Kami tim kecil, dan relawanlah yang membawa karya ini ke setiap bahasa dan setiap penjuru dunia.","rolesH2":"Cara Anda bisa membantu","rolesSub":"Pilih yang sesuai dengan Anda. Tidak perlu pengalaman teknis, cukup keikhlasan, ketelitian, dan sedikit waktu.","roleCta":"Saya bisa membantu","roles":{"translate":{"title":"Penerjemah","text":"Hadirkan aplikasi, situs web, doa, dan kisah mingguan dalam bahasa Anda: Indonesia, Melayu, Arab, Urdu, Prancis, Spanyol, Turki, Bengali, Hindi, dan lainnya. Setiap terjemahan kami periksa sebelum terbit.","time":"Mulai 1\u20132 jam per minggu"},"recite":{"title":"Qari","text":"Jika Allah menganugerahi Anda suara yang indah dan tajwid yang benar, rekam bacaan Al-Qur\u2019an, doa, atau azan untuk pendengar di seluruh dunia. Kami bantu soal perekaman dan penyuntingan.","time":"Rekam sesuai waktu Anda"},"review":{"title":"Ulama dan peninjau","text":"Penuntut ilmu, imam, dan guru: periksa ketepatan dan sumber terjemahan, kisah, dan jawaban kuis, agar semua yang kami terbitkan dapat dipercaya.","time":"Tinjau kapan pun Anda bisa"},"write":{"title":"Penulis dan pencerita","text":"Bantu menulis kisah mingguan para Nabi, Sahabat, dan Sirah untuk keluarga dan anak-anak, dalam bahasa Indonesia atau bahasa lain, selalu dari sumber yang sahih.","time":"Satu kisah per bulan sudah sangat membantu"},"test":{"title":"Penguji","text":"Coba fitur baru sebelum dirilis di iPhone, Android, atau Alexa, lalu beri tahu kami apa yang terasa salah atau membingungkan. Mata yang segar melihat apa yang kami lewatkan.","time":"Beberapa menit per rilis"},"masjid":{"title":"Duta masjid","text":"Bantu masjid setempat menerbitkan jadwal iqamah dan salat Jumat agar jamaahnya dapat melihatnya di aplikasi, situs web, dan Alexa. Gratis untuk setiap masjid.","time":"Satu percakapan dapat melayani seluruh jamaah"}},"stepsH2":"Cara kerjanya","steps":{"s1":{"title":"Kirim email","text":"Sebutkan peran yang Anda pilih, bahasa yang Anda kuasai, dan sedikit tentang diri Anda."},"s2":{"title":"Kami membalas langsung","text":"Kami menghubungi Anda dengan panduan singkat dan tugas kecil pertama."},"s3":{"title":"Karya Anda terbit","text":"Setelah ditinjau, kontribusi Anda sampai ke orang-orang di seluruh dunia."}},"promiseH2":"Yang bisa Anda harapkan dari kami","promise":{"p1":{"title":"Waktu Anda, ritme Anda","text":"Tanpa komitmen minimum. Bantu saat bisa, berhenti sejenak saat perlu."},"p2":{"title":"Nama Anda, jika berkenan","text":"Kami senang berterima kasih dengan menyebut nama Anda, atau menjaga bantuan Anda antara Anda dan Allah. Pilihan Anda."},"p3":{"title":"Teliti dan akurat","text":"Konten keagamaan ditinjau dan diberi sumber sebelum terbit. Anda tidak menanggungnya sendirian."},"p4":{"title":"Privasi Anda dihormati","text":"Kami memakai email Anda hanya untuk bekerja sama dengan Anda, tidak pernah membagikannya atau memasukkannya ke milis."}},"finalH2":"Siap membantu?","finalText":"Kirimkan satu email kepada kami. Meski belum yakin peran apa yang cocok, tulis saja, insya Allah kita temukan tempat yang tepat bersama."}')}}]);